class Trie {
  constructor() {
    this.root = {};
  }
  insert(word) {
    let node = this.root;
    for (const ch of word) {
      node[ch] = node[ch] || {};
      node = node[ch];
    }
    node.end = true;
  }
  walk(s) {
    let node = this.root;
    for (const ch of s) {
      if (!node[ch]) return null;
      node = node[ch];
    }
    return node;
  }
  search(word) {
    const node = this.walk(word);
    return node !== null && node.end === true;
  }
  startsWith(prefix) {
    return this.walk(prefix) !== null;
  }
}

