function shortestPath(graph, start, end) {
  const dist = { [start]: 0 };
  const done = new Set();
  while (true) {
    let u = null;
    for (const n in dist) {
      if (!done.has(n) && (u === null || dist[n] < dist[u])) u = n;
    }
    if (u === null) break;
    done.add(u);
    for (const [v, w] of graph[u]) {
      if (dist[u] + w < (dist[v] ?? Infinity)) dist[v] = dist[u] + w;
    }
  }
  return end in dist ? dist[end] : -1;
}
